"""Tests of the fake GNSS receiver's pure parts (navera_lite/ros/gps_node.py, mission 10).
Written for the course; it is not NAVERA code.

Run from the lesson folder:  python3 -m pytest navera_lite/tests/test_gps_node.py -q
"""
import math

import pytest

from navera_lite.geo import haversine_m
from navera_lite.ros.convert import stamp_to_s
from navera_lite.ros.gps_node import covariance_from_sigma, make_fix, step

START = (35.8256, 10.6084)


def test_step_moves_along_the_heading():
    lat, lon = step(*START, 10.0, 90.0, 0.62)
    assert lat == pytest.approx(START[0], abs=1e-9) and lon > START[1]
    assert haversine_m(*START, lat, lon) == pytest.approx(6.2, rel=1e-3)
    lat, lon = step(*START, 10.0, 0.0, 1.0)
    assert lat > START[0] and lon == pytest.approx(START[1], abs=1e-12)
    with pytest.raises(ValueError):
        step(*START, 10.0, 0.0, -0.1)


def test_real_dt_not_nominal_dt():
    lat, lon = START
    for dt in (0.50, 0.62, 0.41, 0.55):
        lat, lon = step(lat, lon, 10.0, 90.0, dt)
    assert haversine_m(*START, lat, lon) == pytest.approx(20.8, rel=1e-3)


def test_covariance_is_honest():
    assert covariance_from_sigma(3.0) == ([9.0, 0.0, 0.0, 0.0, 9.0, 0.0, 0.0, 0.0, 36.0], 1)
    for unknown in (None, 0.0, -1.0, math.nan, True):
        assert covariance_from_sigma(unknown) == ([0.0] * 9, 0)
    cov, _ = covariance_from_sigma(2)
    assert all(isinstance(v, float) for v in cov)


def test_make_fix_fills_every_field():
    m = make_fix(35.8256, 10.6084, 40.0, 3.0, 100.5)
    assert stamp_to_s(m.header.stamp) == 100.5 and m.header.frame_id == "gps"
    assert (m.status.status, m.status.service) == (0, 1)
    assert (m.latitude, m.longitude, m.altitude) == (35.8256, 10.6084, 40.0)
    assert list(m.position_covariance) == [9.0, 0.0, 0.0, 0.0, 9.0, 0.0, 0.0, 0.0, 36.0]
    assert m.position_covariance_type == 1
    assert make_fix(35.8256, 10.6084, 40.0, 0.0, 1.0).position_covariance_type == 0
